def safe_directory(path,new=False):
    canonical(str(path));p=Path(path)
    for ancestor in (p,*p.parents):
        if ancestor.exists():need(not ancestor.is_symlink() and not ancestor.is_junction() and canonical(str(ancestor.resolve(strict=True)))==canonical(str(ancestor)),'DIRECTORY_ALIAS')
    need(p.parent.is_dir() and (not p.exists() if new else p.is_dir()),'DIRECTORY_EXISTENCE')
    return p

